macro_rules! InlineArray {
    () => {
        # [doc = " A fixed capacity array sized to match some other type `T`."] # [doc = ""] # [doc = " This works like a vector, but allocated on the stack (and thus marginally"] # [doc = " faster than `Vec`), with the allocated space exactly matching the size of"] # [doc = " the given type `T`. The vector consists of a `usize` tracking its current"] # [doc = " length and zero or more elements of type `A`. The capacity is thus"] # [doc = " `( size_of::<T>() - size_of::<usize>() ) / size_of::<A>()`. This could lead"] # [doc = " to situations where the capacity is zero, if `size_of::<A>()` is greater"] # [doc = " than `size_of::<T>() - size_of::<usize>()`, which is not an error and"] # [doc = " handled properly by the data structure."] # [doc = ""] # [doc = " If `size_of::<T>()` is less than `size_of::<usize>()`, meaning the vector"] # [doc = " has no space to store its length, `InlineArray::new()` will panic."] # [doc = ""] # [doc = " This is meant to facilitate optimisations where a list data structure"] # [doc = " allocates a fairly large struct for itself, allowing you to replace it with"] # [doc = " an `InlineArray` until it grows beyond its capacity. This not only gives you"] # [doc = " a performance boost at very small sizes, it also saves you from having to"] # [doc = " allocate anything on the heap until absolutely necessary."] # [doc = ""] # [doc = " For instance, `im::Vector<A>` in its final form currently looks like this"] # [doc = " (approximately):"] # [doc = ""] # [doc = " ```rust, ignore"] # [doc = " struct RRB<A> {"] # [doc = "     length: usize,"] # [doc = "     tree_height: usize,"] # [doc = "     outer_head: Rc<Chunk<A>>,"] # [doc = "     inner_head: Rc<Chunk<A>>,"] # [doc = "     tree: Rc<TreeNode<A>>,"] # [doc = "     inner_tail: Rc<Chunk<A>>,"] # [doc = "     outer_tail: Rc<Chunk<A>>,"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " That's two `usize`s and five `Rc`s, which comes in at 56 bytes on x86_64"] # [doc = " architectures. With `InlineArray`, that leaves us with 56 -"] # [doc = " `size_of::<usize>()` = 48 bytes we can use before having to expand into the"] # [doc = " full data struture. If `A` is `u8`, that's 48 elements, and even if `A` is a"] # [doc = " pointer we can still keep 6 of them inline before we run out of capacity."] # [doc = ""] # [doc = " We can declare an enum like this:"] # [doc = ""] # [doc = " ```rust, ignore"] # [doc = " enum VectorWrapper<A> {"] # [doc = "     Inline(InlineArray<A, RRB<A>>),"] # [doc = "     Full(RRB<A>),"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " Both of these will have the same size, and we can swap the `Inline` case out"] # [doc = " with the `Full` case once the `InlineArray` runs out of capacity."] # [repr (C)] pub struct InlineArray < A , T > { _header_align : [(u64 , usize) ; 0] , _phantom : PhantomData < A > , data : MaybeUninit < T > , }
    };
}

InlineArray!()